import{c as a,a6 as t,x as e,A as r,e as s,h as o,k as l,n as i}from"./chunks/framework.D70RugSU.js";const g=JSON.parse('{"title":"北海道旅","description":"","frontmatter":{"title":"北海道旅","date":"2026-04-27T00:00:00.000Z","outline":[2,3],"lastUpdated":true,"sidebar":false,"tags":["旅","北海道"]},"headers":[],"relativePath":"posts/hkd-travel.md","filePath":"posts/hkd-travel.md","lastUpdated":1780068535000}'),d={name:"posts/hkd-travel.md"};function _(n,p,c,h,m,u){return t(),e("div",null,[...p[0]||(p[0]=[r('<h1 id="🎥-北海道一周の旅-day-1" tabindex="-1">🎥 北海道一周の旅｜Day 1 <a class="header-anchor" href="#🎥-北海道一周の旅-day-1" aria-label="Permalink to “🎥 北海道一周の旅｜Day 1”">​</a></h1><h2 id="_4月26日-夜出発-〜-新潟へ" tabindex="-1">4月26日 夜出発 〜 新潟へ <a class="header-anchor" href="#_4月26日-夜出発-〜-新潟へ" aria-label="Permalink to “4月26日 夜出発 〜 新潟へ”">​</a></h2><h3 id="_4月26日-夜出发-前往新潟" tabindex="-1">4月26日 夜出发 ～ 前往新潟 <a class="header-anchor" href="#_4月26日-夜出发-前往新潟" aria-label="Permalink to “4月26日 夜出发 ～ 前往新潟”">​</a></h3><p>4月26日の夜。 いよいよ北海道一周の旅がスタートします。</p><p>4月26日的夜晚。 北海道一周之旅，终于开始了。</p><p>浜松を出発して、まずは国道1号線へ。 夜のドライブは静かで、ちょっとワクワクしますね。</p><p>从滨松出发，先驶上国道1号线。 夜晚的驾驶很安静，让人有一点小小的兴奋。</p><p>そのまま北へ向かい、静岡を抜けて山梨方面へ。 この日は無理せず、道の駅で車中泊。 長旅の始まりなので、まずはしっかり休みます。</p><p>一路向北，穿过静冈，朝山梨方向前进。 这一天不勉强赶路，在道之站车中住宿。 毕竟是长途旅行的开始，先好好休息。</p><p>翌朝、4月27日。 目が覚めると……雨。</p><p><img src="'+s+'" alt="&quot;道の駅　南部&quot;" loading="lazy"></p><p>第二天，4月27日。 醒来时……外面在下雨。</p><p>ちょっとテンションは下がりますが、気にせず出発。 中部横断自動車道から長野方面へ向かいます。</p><p>虽然情绪有点低落，但还是照常出发。 从中部横断自动车道前往长野方向。</p><p>途中、諏訪湖サービスエリアで少し休憩。 雨に煙る湖も、これはこれで悪くないですね。</p><p><img src="'+o+'" alt="&quot;諏訪湖PA&quot;" loading="lazy"></p><p>途中在诹访湖服务区稍作休息。 被雨雾笼罩的湖面，也别有一番味道。</p><p>そのあと高速を降りたのですが…… まさかの道間違い。</p><p>之后下了高速…… 没想到居然走错了路。</p><p>仕方なく、もう一度高速に乗り直して上田方面へ。 旅にはこういうハプニングもつきものです。</p><p>没办法，只好重新上高速，往上田方向走。 旅行中总会有这样的意外。</p><p>雨のせいか気温も低くて、かなり寒い。 春のはずなのに、まだ冬みたいな空気です。</p><p>可能因为下雨，气温很低，感觉相当冷。 明明已经是春天，却像冬天一样。</p><p>お昼12時ごろ、千曲市に到着。 ここは北信地方。 山を越えれば、いよいよ新潟県です。</p><p>中午12点左右到达千曲市。 这里属于北信地区。 翻过山，就要进入新潟县了。</p><p><img src="'+l+'" alt="&quot;諏訪湖PA&quot;" loading="lazy"></p><p>少し遅めのお昼ごはんを食べて、ひと休み。 体も気持ちもリセット。</p><p>吃了稍晚一点的午饭，休息一下。 身体和心情都重新调整。</p><p>午後、再び山道へ。</p><p>下午，再次进入山路。</p><p>長野市を過ぎたあたりで、ようやく雨が止みました。 空も少し明るくなってきます。</p><p>经过长野市后，雨终于停了。 天空也慢慢亮了起来。</p><p>午後3時ごろ、新潟県に入りました。 なんとなく「北へ来たな」という感じがします。</p><p>下午3点左右进入新潟县。 隐隐感觉，真的来到更北方了。</p><p>時間にも余裕があったので、 国道8号線をゆっくり流しながら新潟市へ。</p><p>时间还算充裕， 于是沿着国道8号线慢慢前往新潟市。</p><p>海沿いの道は、走っているだけで気持ちいい。</p><p>沿海的道路，只是开着车就让人心情很好。</p><p>そして夕方6時ごろ、新潟市に到着。</p><p>傍晚6点左右，抵达新潟市。</p><p><img src="'+i+'" alt="&quot;日本海&quot;" loading="lazy"></p><p>今日一日で、かなり距離を走りました。 でも、まだこれは旅の序章。</p><p>今天一天开了相当远的距离。 但这还只是旅程的序章。</p><p>ここから、いよいよ北海道へ向かいます。</p><p>接下来，真正要向北海道前进了。</p>',45)])])}const k=a(d,[["render",_]]);export{g as __pageData,k as default};
